import{_ as n,a0 as p,w as r,s as o,ao as d,I as l,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何逐步安裝 Kubernetes（k8s）指標服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何逐步安裝 Kubernetes（k8s）指標服務器 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何逐步安裝 Kubernetes（k8s）指標服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何逐步安裝 Kubernetes（k8s）指標服務器 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230327.0 ⭐️ How to Install Kubernetes (K8s) Metrics Server Step by Step","title":"如何逐步安裝 Kubernetes（k8s）指標服務器","tag":"202304","desc":""},"relativePath":"202304/20230327.0 ⭐️ How to Install Kubernetes (K8s) Metrics Server Step by Step.md","filePath":"[post].md"}'),h={name:"202304/20230327.0 ⭐️ How to Install Kubernetes (K8s) Metrics Server Step by Step.md"};function u(c,e,b,g,k,m){const s=p("Link");return r(),o("div",null,[e[15]||(e[15]=d(`<h1 id="如何逐步安裝-kubernetes-k8s-指標服務器" tabindex="-1">如何逐步安裝 Kubernetes（k8s）指標服務器 <a class="header-anchor" href="#如何逐步安裝-kubernetes-k8s-指標服務器" aria-label="Permalink to “如何逐步安裝 Kubernetes（k8s）指標服務器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/12/100919k6p6yyweu6nv6nkh.jpg" alt=""></p><blockquote><p>在這篇文章中，我們將逐步介紹如何安裝 Kubernetes 指標服務器。</p></blockquote><p>Kubernetes（k8s）指標服務器是一個組件，用於收集和聚合來自 Kubernetes 集羣中各種來源（包括節點和 <ruby>容器莢<rt>Pod</rt></ruby>）的指標數據。此數據可用於監控和優化資源利用率、識別潛在問題並提高 Kubernetes 集羣的整體性能。</p><p>指標服務器收集資源利用率數據，例如集羣中節點和容器莢的 CPU 和內存使用情況。它提供了一個 API 端點，可用於查詢此數據並檢索集羣中特定資源的指標。</p><h5 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h5><ul><li>啓動並運行 Kubernetes 集羣（v1.21 或更高版本）。</li><li><code>kubectl</code> 命令列工具已安裝，並配置為與你的 Kubernetes 集羣交互。</li><li>創建和修改 Kubernetes 對象的能力。</li></ul><p>事不宜遲，讓我們深入瞭解安裝步驟。</p><h3 id="步驟-1-下載指標服務器清單" tabindex="-1">步驟 1 下載指標服務器清單 <a class="header-anchor" href="#步驟-1-下載指標服務器清單" aria-label="Permalink to “步驟 1 下載指標服務器清單”">​</a></h3><p>第一步是從 Kubernetes GitHub 倉庫下載最新的指標服務器清單文件。使用下面的 <code>curl</code> 命令下載 yaml 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># curl -LO https://github.com/kubernetes-sigs/metrics-server/releases/latest/download/components.yaml</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Download-Metrics-Server-Yaml-file-Curl-Command-1024x127.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>如果你計劃在高可用性模式下安裝指標服務器，請下載以下清單文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># curl https://github.com/kubernetes-sigs/metrics-server/releases/latest/download/high-availability-1.21+.yaml</span></span></code></pre></div><h3 id="步驟-2-修改指標服務器-yaml-文件" tabindex="-1">步驟 2 修改指標服務器 Yaml 文件 <a class="header-anchor" href="#步驟-2-修改指標服務器-yaml-文件" aria-label="Permalink to “步驟 2 修改指標服務器 Yaml 文件”">​</a></h3><p>接下來，你需要修改指標服務器的 yaml 文件以設置一些配置選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi components.yaml</span></span></code></pre></div><p>找到 <code>container</code> 下的 <code>args</code> 部分，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- --kubelet-insecure-tls</span></span></code></pre></div><p>在 <code>spec</code> 下，添加以下參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hostNetwork: true</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Edit-Metrics-Server-Yaml-file.png" alt=""></p><p>保存並關閉文件。</p><h3 id="步驟-3-部署指標服務器" tabindex="-1">步驟 3 部署指標服務器 <a class="header-anchor" href="#步驟-3-部署指標服務器" aria-label="Permalink to “步驟 3 部署指標服務器”">​</a></h3><p>現在，我們準備好部署指標服務器，運行以下 <code>kubectl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl apply -f components.yaml</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Deploy-Metrics-Server-Kubectl-Command.png" alt=""></p><h3 id="步驟-4-驗證指標服務器部署" tabindex="-1">步驟 4 驗證指標服務器部署 <a class="header-anchor" href="#步驟-4-驗證指標服務器部署" aria-label="Permalink to “步驟 4 驗證指標服務器部署”">​</a></h3><p>部署指標服務器後，通過檢查在 <code>kube-system</code> 命名空間中運行的容器莢狀態來驗證它的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl get pods -n kube-system</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Metrics-Server-Pods-Status-Kube-System.png" alt=""></p><p>上面的輸出確認指標服務器容器莢已啓動並正在運行。</p><h3 id="步驟-5-測試指標服務器安裝" tabindex="-1">步驟 5 測試指標服務器安裝 <a class="header-anchor" href="#步驟-5-測試指標服務器安裝" aria-label="Permalink to “步驟 5 測試指標服務器安裝”">​</a></h3><p>最後，你可以通過運行以下 <code>kubectl</code> 命令來測試指標服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl top nodes</span></span></code></pre></div><p>此命令應顯示集羣中每個節點的資源利用率，包括 CPU 和內存使用率。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Kubectl-top-node-command-Output.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>要查看當前命名空間或特定命名空間的容器莢資源利用率，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># kubectl top pod</span></span>
<span class="line"><span># kubectl top pod -n kube-system</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Kubectl-top-pod-command-output.png" alt=""></p><p>這就是這篇文章的全部內容，我希望你能從中找到有用的信息。請在下面的評論部分發表你的反饋和疑問。</p><p><em>（題圖：MJ: Kubernetes container paper art light blue background ultra-detailed topview）</em></p><hr>`,43)),l("p",null,[e[1]||(e[1]=t("via: ",-1)),i(s,{href:"https://www.linuxtechi.com/how-to-install-kubernetes-metrics-server/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.linuxtechi.com/how-to-install-kubernetes-metrics-server/",-1)])]),_:1})]),l("p",null,[e[6]||(e[6]=t("作者：",-1)),i(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...e[2]||(e[2]=[t("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),i(s,{href:"https://github.com/lkxed/"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:a(()=>[...e[4]||(e[4]=[t("geekpi",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[12]||(e[12]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const x=n(h,[["render",u]]);export{w as __pageData,x as default};
